<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/admin_layout.php'))require_once __DIR__.'/../app/admin_layout.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/services_v1380.php';if(!sk1380_admin()){http_response_code(403);exit('Access denied.');}$rows=[];$err='';try{$q=sk1380_db()->prepare('SELECT o.*,p.business_name,p.display_name FROM service_orders_v1380 o JOIN service_provider_profiles_v1380 p ON p.id=o.provider_id WHERE o.tenant_id=? ORDER BY FIELD(o.status,"booked","accepted","on_the_way","started","completed","cancelled"),o.id DESC LIMIT 300');$q->execute([sk1380_tid()]);$rows=$q->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){$err=$e->getMessage();}sk1380_admin_header('Service Orders');?><div class="svc-admin"><?php if($err):?><div class="notice err"><b>Orders runtime check failed.</b> <?=sk1380_h($err)?></div><?php endif;?><section class="admin-hero"><div><span>ORDER OPERATIONS</span><h1>Service Orders</h1><p>Operational view of accepted quotes and provider job lifecycle.</p></div><a href="/admin/services.php">← Dashboard</a></section><div class="order-list admin-orders"><?php foreach($rows as $o):?><a href="/service-order.php?id=<?=$o['id']?>"><span><?=sk1380_h($o['order_code'])?></span><h3><?=sk1380_h($o['service_title'])?></h3><p><?=sk1380_h($o['business_name']?:$o['display_name'])?> · customer #<?=$o['customer_user_id']?></p><b><?=sk1380_h(strtoupper($o['status']))?></b><strong>PKR <?=number_format((float)$o['total_amount'],0)?></strong></a><?php endforeach;?></div></div><?php sk1380_admin_footer();